/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name="sender">SalesQuotationTableDS</param>
/// <param name="e">FormDataSourceEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormDataSourceEventHandler(formDataSourceStr(SalesQuotationTable, SalesQuotationTable), FormDataSourceEventType::Activated)]
public static void SalesQuotationTable_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    SalesQuotationTable                     salesQuotationTable;
    KCS_HDMSalesQuotationTableInfoFields    infoFields;
    FormRun                                 formRun;
    FormButtonControl                       button;

    FormDataSource dataSource   = sender.formRun().dataSource(formDataSourceStr (SalesQuotationTable, SalesQuotationTable));
    salesQuotationTable         = dataSource.cursor() as SalesQuotationTable;
    infoFields                  = KCS_HDMSalesQuotationTableInfoFields::find(salesQuotationTable.QuotationId);
    formRun                     = sender.formRun();
    button = formRun.design().controlName(formControlStr(SalesQuotationTable, AVASQInfoFields)) as FormButtonControl;
    if (infoFields.InfoField1 || infoFields.InfoField2 || infoFields.InfoField3 || infoFields.InfoField4 )
    {
        button.toggleButton(ToggleButtonStyle::Check);
        button.toggleValue(OnOff::On);
    }
    else
    {
        button.toggleButton(ToggleButtonStyle::None);
        button.toggleValue(OnOff::Off);
    }

    sender.formRun().design().controlName('AVAQuotExcel').enabled(salesQuotationTable.lastQuotation() != '');
}

